/*
 * mst_$unwire_page - give back the physical page behind one MST table page
 *
 * Original address: 0x00E74A74 (module-local; the SAU2 map has no symbol
 * here - it is the first routine of the MST_UNWIRED code segment E74A74,
 * size 0x1B0, before mst_$unwire_asid_pages and MST_$FREE_ASID)
 * Size: 66 bytes (0x00E74A74 .. 0x00E74AB5)
 * Generated by: Claude Opus 5.5
 *
 * Frame (link.w A6,-0xc; no registers saved):
 *   (0x08,A6)  va      longword: the VA of the page-table page
 *   (-0x08,A6) status  filled by MMU_$VTOP
 *   (-0x0C,A6) ppn     MMU_$VTOP's result
 *
 * Blocks:
 *   0x00E74A78-0x00E74A88  ppn := MMU_$VTOP(va, &status)
 *   0x00E74A8C-0x00E74AA6  status = 0: MMU_$REMOVE(ppn); MMAP_$FREE(ppn)
 *   0x00E74AA8-0x00E74AB2  otherwise CRASH_SYSTEM(&status)
 */

#include "mst/mst_internal.h"
#include "misc/crash_system.h"

void mst_$unwire_page(uint32_t va)
{
    status_$t status;       /* (-0x8,A6) */
    uint32_t ppn;           /* (-0xc,A6) */

    /* 0x00E74A78-0x00E74A88 */
    ppn = MMU_$VTOP(va, &status);

    /* 0x00E74A8C tst.l (-0x8,A6) / bne */
    if (status == status_$ok) {
        /* 0x00E74A92-0x00E74AA6 */
        MMU_$REMOVE(ppn);
        MMAP_$FREE(ppn);
    } else {
        /* 0x00E74AA8-0x00E74AB2 */
        CRASH_SYSTEM(&status);
    }
}
